// Drives the real Pages pipeline end to end for the two demo brands, the way
// a merchant would through the console: intake from the local demo sites,
// audiences (location, demographics, interests, CSV clusters, a personal
// lead), pages with one variant per audience generated by the agent, publish,
// then simulated traffic so the analytics have something to show.
//
//   pnpm --filter @slice/demo-data seed                 both brands, reuse what exists
//   pnpm --filter @slice/demo-data seed -- --only ridgeline
//   pnpm --filter @slice/demo-data seed -- --reset      wipe the demo brands first
//   pnpm --filter @slice/demo-data seed -- --no-traffic
//
// Needs: convex dev deployment (packages/backend/.env.local), the agent on
// AGENT_URL (default :8000), the demo stores on STORES_URL (default :3002).
// Idempotent: brands, audiences and pages are found by slug; variants that are
// already "ready" are not regenerated.

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";
import { ConvexHttpClient } from "convex/browser";
import { api } from "@slice/backend/convex/_generated/api.js";

const root = path.resolve(import.meta.dirname, "..", "..", "..");
const args = process.argv.slice(2);
const flag = (name: string) => args.includes(name);
const only = args[args.indexOf("--only") + 1];
const RESET = flag("--reset");
const TRAFFIC = !flag("--no-traffic");

function envFrom(file: string): Record<string, string> {
  try {
    return Object.fromEntries(
      readFileSync(file, "utf8")
        .split("\n")
        .filter((l) => /^[A-Z_]+=/.test(l))
        .map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1).trim().replace(/^"|"$/g, "")]),
    );
  } catch {
    return {};
  }
}
const backendEnv = envFrom(path.join(root, "packages/backend/.env.local"));
const CONVEX_URL = process.env.CONVEX_URL ?? backendEnv.CONVEX_URL;
if (!CONVEX_URL) throw new Error("CONVEX_URL missing (packages/backend/.env.local)");
const AGENT_URL = process.env.AGENT_URL ?? "http://localhost:8000";
const STORES_URL = process.env.STORES_URL ?? "http://localhost:3002";
const PAGES_HOST = process.env.NEXT_PUBLIC_PAGES_HOST ?? "pages.localhost:3000";

const convex = new ConvexHttpClient(CONVEX_URL);
const log = (msg: string) => console.log(`${new Date().toISOString().slice(11, 19)}  ${msg}`);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/* Agent streams ------------------------------------------------------------- */

async function stream(pathname: string, body: unknown, onEvent?: (e: Record<string, unknown>) => void) {
  const res = await fetch(`${AGENT_URL}${pathname}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok || !res.body) throw new Error(`${pathname} → ${res.status} ${await res.text()}`);
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let last: Record<string, unknown> = {};
  const handle = (line: string) => {
    if (!line.trim()) return;
    try {
      const ev = JSON.parse(line) as Record<string, unknown>;
      last = ev;
      if (ev.type === "error") throw new Error(`agent error: ${String(ev.message)}`);
      onEvent?.(ev);
    } catch (err) {
      if (err instanceof SyntaxError) return;
      throw err;
    }
  };
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let nl: number;
    while ((nl = buffer.indexOf("\n")) >= 0) {
      handle(buffer.slice(0, nl));
      buffer = buffer.slice(nl + 1);
    }
  }
  if (buffer.trim()) handle(buffer);
  return last;
}

async function post(pathname: string, body: unknown) {
  const res = await fetch(`${AGENT_URL}${pathname}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`${pathname} → ${res.status} ${await res.text()}`);
  return (await res.json()) as Record<string, unknown>;
}

/* Convex helpers --------------------------------------------------------------- */

type Id = string;
type AnyDoc = Record<string, any>;

async function waitFor<T extends AnyDoc>(read: () => Promise<T | null>, ready: (d: T) => boolean, label: string, timeoutMs = 600_000): Promise<T> {
  const t0 = Date.now();
  let lastLabel = "";
  for (;;) {
    const d = await read();
    if (d && ready(d)) return d;
    if (d?.status === "failed") throw new Error(`${label} failed: ${d.error ?? "unknown"}`);
    const p = d?.progress?.label;
    if (p && p !== lastLabel) {
      log(`   ${label}: ${p}`);
      lastLabel = p;
    }
    if (Date.now() - t0 > timeoutMs) throw new Error(`${label}: timed out`);
    await sleep(2500);
  }
}

function convexRun(fn: string, argsJson: Record<string, unknown>) {
  return execFileSync("npx", ["convex", "run", fn, JSON.stringify(argsJson)], {
    cwd: path.join(root, "packages/backend"),
    encoding: "utf8",
    stdio: ["ignore", "pipe", "inherit"],
  });
}

/* CSV ---------------------------------------------------------------------------- */

function parseCsv(text: string): { columns: string[]; rows: Record<string, string>[] } {
  const lines: string[][] = [];
  let row: string[] = [];
  let cell = "";
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (c === '"') quoted = false;
      else cell += c;
    } else if (c === '"') quoted = true;
    else if (c === ",") {
      row.push(cell);
      cell = "";
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      row.push(cell);
      cell = "";
      if (row.some((v) => v !== "")) lines.push(row);
      row = [];
    } else cell += c;
  }
  if (cell || row.length) {
    row.push(cell);
    if (row.some((v) => v !== "")) lines.push(row);
  }
  const [columns, ...rest] = lines;
  return { columns, rows: rest.map((r) => Object.fromEntries(columns.map((c, i) => [c, r[i] ?? ""]))) };
}

/* Steps ------------------------------------------------------------------------ */

async function ensureBrand(name: string, url: string, slug: string): Promise<AnyDoc> {
  let brand = (await convex.query(api.pagesBrands.bySlug, { slug })) as AnyDoc | null;
  if (brand && RESET) {
    log(`Resetting ${slug}`);
    convexRun("pagesSeed:reset", { brandSlug: slug });
    brand = null;
  }
  if (!brand) {
    const created = (await convex.mutation(api.pagesBrands.create, { name, url, slug })) as { id: Id; slug: string };
    log(`Created brand ${created.slug}; running intake on ${url}`);
    await stream("/pages/intake", { brand_id: created.id, url }, (ev) => {
      if (ev.type === "status") log(`   intake: ${String(ev.text)}`);
    });
    brand = await waitFor(() => convex.query(api.pagesBrands.get, { id: created.id as any }) as Promise<AnyDoc | null>, (b) => b.status === "review" || b.status === "ready", "intake");
    await convex.mutation(api.pagesBrands.markReady, { id: created.id as any });
    brand = (await convex.query(api.pagesBrands.get, { id: created.id as any })) as AnyDoc;
    log(`   kit: ${brand.kit?.fonts?.heading?.family} / ${brand.kit?.fonts?.body?.family}, primary ${brand.kit?.colors?.primary}; ${brand.brief?.items?.length ?? 0} items; Qloo ${brand.qloo?.matched ? "matched" : `${brand.qloo?.proxies?.length ?? 0} proxies`}`);
  } else {
    log(`Brand ${slug} exists (${brand.status}); reusing`);
  }
  return brand;
}

async function ensureAudience(brand: AnyDoc, name: string, kind: string, sources: Record<string, unknown>): Promise<AnyDoc> {
  const existing = (await convex.query(api.pagesAudiences.list, { brandId: brand._id })) as AnyDoc[];
  let a = existing.find((x) => x.name === name);
  if (!a) {
    const { id } = (await convex.mutation(api.pagesAudiences.create, { brandId: brand._id, name, kind, sources } as any)) as { id: Id };
    log(`Audience "${name}" (${kind}): compiling`);
    await convex.action(api.pagesAudiences.compile, { id: id as any });
    a = await waitFor(() => convex.query(api.pagesAudiences.get, { id: id as any }) as Promise<AnyDoc | null>, (d) => d.status === "ready", `audience ${name}`);
  }
  if (!a.brief) {
    const r = await post("/pages/audience-brief", { audience_id: a._id });
    log(`   brief for "${name}": ${r.ok ? String((r.brief as AnyDoc)?.summary ?? "").slice(0, 90) : `failed ${String(r.error)}`}`);
    a = (await convex.query(api.pagesAudiences.get, { id: a._id })) as AnyDoc;
  }
  return a;
}

async function ensureUpload(brand: AnyDoc, file: string, mapping: Record<string, unknown>, k?: number): Promise<{ upload: AnyDoc; audiences: AnyDoc[] }> {
  const filename = path.basename(file);
  const uploads = (await convex.query(api.pagesUploads.list, { brandId: brand._id })) as AnyDoc[];
  let upload = uploads.find((u) => u.filename === filename && u.status === "ready");
  if (!upload) {
    const { columns, rows } = parseCsv(readFileSync(file, "utf8"));
    const { id } = (await convex.mutation(api.pagesUploads.create, { brandId: brand._id, filename, columns, rows: rows.slice(0, 200), mapping } as any)) as { id: Id };
    for (let i = 200; i < rows.length; i += 200) {
      await convex.mutation(api.pagesUploads.appendRows, { uploadId: id as any, rows: rows.slice(i, i + 200) });
    }
    log(`Uploaded ${filename} (${rows.length} rows); resolving taste terms with Qloo and clustering`);
    await convex.action(api.pagesUploads.process, { uploadId: id as any, k });
    upload = await waitFor(() => convex.query(api.pagesUploads.get, { id: id as any }) as Promise<AnyDoc | null>, (u) => u.status === "ready", "upload", 900_000);
    log(`   ${upload.clusters.length} clusters: ${upload.clusters.map((c: AnyDoc) => `${c.size} (${c.topEntities.slice(0, 3).join(", ")})`).join(" | ")}`);
    const named = await post("/pages/name-clusters", { upload_id: id });
    log(`   named: ${JSON.stringify(named.names)}`);
    upload = (await convex.query(api.pagesUploads.get, { id: id as any })) as AnyDoc;
  } else {
    log(`Upload ${filename} exists; reusing ${upload.clusters.length} clusters`);
  }
  const audiences: AnyDoc[] = [];
  for (const c of upload.clusters) {
    if (!c.audienceId) continue;
    let a = (await convex.query(api.pagesAudiences.get, { id: c.audienceId })) as AnyDoc;
    if (a.status !== "ready") a = await waitFor(() => convex.query(api.pagesAudiences.get, { id: c.audienceId }) as Promise<AnyDoc | null>, (d) => d.status === "ready", `cluster ${c.name}`);
    if (!a.brief) {
      const r = await post("/pages/audience-brief", { audience_id: a._id });
      log(`   brief for cluster "${a.name}": ${r.ok ? "ok" : String(r.error)}`);
      a = (await convex.query(api.pagesAudiences.get, { id: c.audienceId })) as AnyDoc;
    }
    audiences.push(a);
  }
  return { upload, audiences };
}

async function ensureLead(brand: AnyDoc, upload: AnyDoc, pick: (row: Record<string, string>) => boolean): Promise<AnyDoc | null> {
  const members = (await convex.query(api.pagesUploads.members, { uploadId: upload._id, take: 400 })) as AnyDoc[];
  const member = members.find((m) => pick(m.row));
  if (!member) return null;
  const { audienceId } = (await convex.mutation(api.pagesUploads.createLead, { memberId: member._id })) as { audienceId: Id };
  let a = (await convex.query(api.pagesAudiences.get, { id: audienceId as any })) as AnyDoc;
  if (a.status !== "ready") {
    log(`Lead "${a.name}" (member ${member.row.first_name ?? member._id}): compiling`);
    await convex.action(api.pagesAudiences.compile, { id: audienceId as any });
    a = await waitFor(() => convex.query(api.pagesAudiences.get, { id: audienceId as any }) as Promise<AnyDoc | null>, (d) => d.status === "ready", "lead");
  }
  if (!a.brief) await post("/pages/audience-brief", { audience_id: a._id });
  a = (await convex.query(api.pagesAudiences.get, { id: audienceId as any })) as AnyDoc;
  (a as AnyDoc).memberId = member._id;
  return a;
}

interface PageSpec {
  slug: string;
  title: string;
  goal: string;
  prompt: string;
  offer?: string;
  cta: { label: string; href: string };
  pickItems: (items: AnyDoc[]) => string[];
  facts: string[];
  audiences: AnyDoc[];
  imageMode?: string;
  utm?: { param: string; value: string; audienceName: string }[];
  /** CTA click probability per variant name, so the simulated traffic has a story. */
  weights: Record<string, number>;
}

async function ensurePage(brand: AnyDoc, spec: PageSpec): Promise<AnyDoc> {
  const pages = (await convex.query(api.pages.list, { brandId: brand._id })) as AnyDoc[];
  let page = pages.find((p) => p.slug === spec.slug);
  const audienceIds = spec.audiences.map((a) => a._id);
  if (!page) {
    const items: AnyDoc[] = brand.brief?.items ?? [];
    const { id } = (await convex.mutation(api.pages.create, {
      brandId: brand._id,
      title: spec.title,
      slug: spec.slug,
      audienceIds,
      brief: {
        goal: spec.goal,
        prompt: spec.prompt,
        offer: spec.offer,
        cta: spec.cta,
        itemIds: spec.pickItems(items),
        facts: spec.facts,
        references: [],
        inspiration: [],
        imageMode: spec.imageMode ?? "pexels",
      },
    } as any)) as { id: Id };
    log(`Created page ${spec.slug} with ${audienceIds.length} audiences`);
    page = { _id: id };
  } else {
    const current = new Set<string>(page.audienceIds ?? []);
    if (audienceIds.some((a) => !current.has(a))) {
      await convex.mutation(api.pages.setAudiences, { id: page._id, audienceIds: [...new Set([...current, ...audienceIds])] as any });
    }
  }
  let full = (await convex.query(api.pages.get, { id: page._id })) as AnyDoc;
  for (const variant of full.variants as AnyDoc[]) {
    if (variant.status === "ready" && variant.doc) continue;
    log(`   generating "${variant.name}"`);
    const t0 = Date.now();
    let sections = 0;
    await stream("/pages/build", { page_id: full.page._id, variant_id: variant._id, kind: "generate", message: "" }, (ev) => {
      if (ev.type === "doc") sections = ((ev.doc as AnyDoc)?.sections ?? []).length;
    });
    log(`   ${variant.name}: ${sections} sections in ${Math.round((Date.now() - t0) / 1000)}s`);
  }
  full = (await convex.query(api.pages.get, { id: page._id })) as AnyDoc;
  if (spec.utm?.length) {
    const rules = spec.utm
      .map((u) => {
        const a = spec.audiences.find((x) => x.name === u.audienceName);
        return a ? { param: u.param, value: u.value, audienceId: a._id } : null;
      })
      .filter(Boolean);
    await convex.mutation(api.pages.setRouting, { id: full.page._id, routing: { utm: rules } } as any);
  }
  if (full.page.status !== "published") {
    await convex.mutation(api.pages.publish, { id: full.page._id });
    log(`   published ${spec.slug}`);
  }
  return (await convex.query(api.pages.get, { id: page._id })) as AnyDoc;
}

function simulate(page: AnyDoc, weights: Record<string, number>, days = 14, sessionsPerDay = 42) {
  const byId: Record<string, number> = {};
  for (const v of page.variants as AnyDoc[]) {
    const w = weights[v.name] ?? weights.__default;
    if (w !== undefined) byId[v._id] = w;
  }
  const out = convexRun("pagesSeed:simulateTraffic", { pageId: page.page._id, days, sessionsPerDay, weights: byId, seed: 7 });
  log(`   traffic for ${page.page.slug}: ${out.trim().split("\n").pop()}`);
}

const pageUrl = (brand: AnyDoc, slug: string) => `http://${brand.slug}.${PAGES_HOST}/${slug}`;

/* Ridgeline ----------------------------------------------------------------------- */

async function ridgeline() {
  const brand = await ensureBrand("Ridgeline Coffee Roasters", `${STORES_URL}/ridgeline`, "ridgeline");
  const austin = await ensureAudience(brand, "Austin locals", "location", { location: { city: "Austin", country: "US" } });
  const seattle = await ensureAudience(brand, "Seattle commuters", "location", { location: { city: "Seattle", country: "US" } });
  const young = await ensureAudience(brand, "Under 25", "demographic", { demographics: { age: "24_and_younger" } });
  const older = await ensureAudience(brand, "55 and over", "demographic", { demographics: { age: "55_and_older" } });
  const { audiences: clusters } = await ensureUpload(brand, path.join(root, "packages/demo-data/data/ridgeline-customers.csv"), {
    taste: ["favourite_artists", "favourite_brands", "interests"],
    city: "city",
    country: "country",
    age: "age",
    gender: "gender",
    id: "id",
    name: "first_name",
  }, 4);

  const coffees = (items: AnyDoc[]) => items.filter((i) => /coffee|roast|blend|origin|espresso|decaf/i.test(`${i.kind} ${i.name} ${i.tags?.join(" ")}`)).slice(0, 6).map((i) => i.id);
  const gifts = (items: AnyDoc[]) => {
    const g = items.filter((i) => /gift|set|bundle|box/i.test(`${i.name} ${i.tags?.join(" ")}`)).map((i) => i.id);
    return g.length ? g.slice(0, 6) : items.slice(0, 6).map((i) => i.id);
  };
  const plans = (items: AnyDoc[]) => {
    const p = items.filter((i) => /plan|subscription|monthly|rotation/i.test(`${i.kind} ${i.name} ${i.tags?.join(" ")}`)).map((i) => i.id);
    return p.length ? p.slice(0, 4) : items.slice(0, 4).map((i) => i.id);
  };

  const pages: PageSpec[] = [
    {
      slug: "austin",
      title: "Austin café opening",
      goal: "launch",
      prompt: "Our third café opens on East 6th Street in Austin in November. The page should get people to join the opening-week list and learn what Ridgeline is about: the roastery in Portland, the farms we buy from, and the café as a neighbourhood room.",
      offer: "Opening week: a free pour-over for everyone on the list.",
      cta: { label: "Join the opening list", href: `${STORES_URL}/ridgeline/cafes#austin` },
      pickItems: coffees,
      facts: ["1900 E 6th St Suite 101, Austin TX 78702", "Opens November 2026", "Roasted in Portland, shipped weekly", "Cafés in Portland and Seattle since 2019"],
      audiences: [austin],
      weights: { Default: 0.05, "Austin locals": 0.11 },
    },
    {
      slug: "gifting",
      title: "Holiday gifting",
      goal: "sale",
      prompt: "Holiday gift guide: gift sets, a gift subscription and a few coffees that make good presents. Lead with what this audience would actually give or want, keep prices and shipping deadlines clear.",
      offer: "Free shipping on gift sets until 18 December.",
      cta: { label: "Shop gifts", href: `${STORES_URL}/ridgeline/gifts` },
      pickItems: gifts,
      facts: ["Order by 18 December for delivery before the holidays", "Gift notes included free", "Roasted to order every Monday"],
      audiences: clusters,
      weights: { Default: 0.045, __default: 0.08 },
    },
    {
      slug: "subscriptions",
      title: "Subscriptions",
      goal: "subscription",
      prompt: "Get people to start a coffee subscription. Explain the three plans, the roast-to-door timing and that it can be paused any time. Speak to how this audience drinks coffee day to day.",
      offer: "First bag half price.",
      cta: { label: "Start a subscription", href: `${STORES_URL}/ridgeline/subscriptions` },
      pickItems: plans,
      facts: ["Three plans from $18 a bag", "Pause or skip any time", "Ships within 48 hours of roasting"],
      audiences: [young, older, seattle],
      utm: [{ param: "source", value: "qr", audienceName: "Seattle commuters" }],
      weights: { Default: 0.05, "Under 25": 0.075, "55 and over": 0.09, "Seattle commuters": 0.07 },
    },
  ];
  const built: AnyDoc[] = [];
  for (const spec of pages) {
    const p = await ensurePage(brand, spec);
    built.push(p);
    if (TRAFFIC) simulate(p, spec.weights);
  }
  return { brand, pages: built };
}

/* Saltline -------------------------------------------------------------------------- */

async function saltline() {
  const brand = await ensureBrand("Saltline Hotels", `${STORES_URL}/saltline`, "saltline");
  const london = await ensureAudience(brand, "Londoners", "location", { location: { city: "London", country: "GB" } });
  const newYork = await ensureAudience(brand, "New Yorkers", "location", { location: { city: "New York City", country: "US" } });
  const berlin = await ensureAudience(brand, "Berliners", "location", { location: { city: "Berlin", country: "DE" } });
  const { upload, audiences: clusters } = await ensureUpload(brand, path.join(root, "packages/demo-data/data/saltline-guests.csv"), {
    taste: ["favourite_artists", "favourite_films", "favourite_places", "interests", "experiences_booked"],
    city: "home_city",
    country: "home_country",
    age: "age",
    gender: "gender",
    id: "id",
    name: "first_name",
  });
  const lead = await ensureLead(brand, upload, (row) => row.home_city === "London" && Number(row.stays) >= 2 && /Lisbon/.test(row.property));

  const lisbonRooms = (items: AnyDoc[]) => {
    const r = items.filter((i) => /lisbon|lisboa/i.test(`${i.name} ${i.description} ${i.tags?.join(" ")}`)).map((i) => i.id);
    return (r.length ? r : items.map((i) => i.id)).slice(0, 6);
  };
  const experiences = (items: AnyDoc[]) => {
    const e = items.filter((i) => /experience|dinner|walk|morning|class|tour|session/i.test(`${i.kind} ${i.name}`)).map((i) => i.id);
    return (e.length ? e : items.map((i) => i.id)).slice(0, 6);
  };

  const pages: PageSpec[] = [
    {
      slug: "lisbon",
      title: "Saltline Lisbon",
      goal: "booking",
      prompt: "A page for Saltline Lisbon aimed at visitors planning a trip from their home city. Show the rooms, the restaurant and the neighbourhood, and make the neighbourhood guide and dining picks feel like they were chosen for someone with this audience's taste. End with a booking enquiry.",
      offer: "Stay three nights, the third is half price until March.",
      cta: { label: "Check availability", href: `${STORES_URL}/saltline/plan?hotel=lisbon` },
      pickItems: lisbonRooms,
      facts: ["Rua da Boavista 74, 1200-068 Lisboa", "Four room tiers from $190", "Restaurant open to the street, breakfast until noon", "Ten minutes on foot to Cais do Sodré"],
      audiences: [london, newYork, berlin],
      weights: { Default: 0.05, Londoners: 0.09, "New Yorkers": 0.1, Berliners: 0.075 },
    },
    {
      slug: "marseille",
      title: "Marseille, spring",
      goal: "waitlist",
      prompt: "Pre-launch page for Saltline Marseille, opening spring 2027 on the Vieux Port. Collect waitlist sign-ups from past guests. Lead with the side of Marseille this audience will care about and include a short waitlist form (name, email, when they might travel).",
      offer: "Waitlist guests get first pick of opening-month dates.",
      cta: { label: "Join the waitlist", href: "#waitlist" },
      pickItems: experiences,
      facts: ["38 Quai de Rive Neuve, 13007 Marseille", "Opening spring 2027", "32 rooms, a rooftop and a harbour-side restaurant", "Direct trains from Paris in three hours"],
      audiences: lead ? [...clusters, lead] : clusters,
      weights: { Default: 0.04, __default: 0.085 },
    },
  ];
  const built: AnyDoc[] = [];
  for (const spec of pages) {
    const p = await ensurePage(brand, spec);
    built.push(p);
    if (TRAFFIC) simulate(p, spec.weights);
  }
  return { brand, pages: built, lead };
}

/* Run ---------------------------------------------------------------------------------- */

const results: string[] = [];
if (!only || only === "ridgeline") {
  const r = await ridgeline();
  results.push(`Ridgeline console: http://localhost:3000/dashboard/pages/${r.brand.slug}`);
  for (const p of r.pages) results.push(`  ${p.page.title}: ${pageUrl(r.brand, p.page.slug)}  (variants: ${p.variants.map((v: AnyDoc) => v.name).join(", ")})`);
  results.push(`  Austin as a visitor from Austin: ${pageUrl(r.brand, "austin")}?city=Austin`);
  results.push(`  Seattle QR poster: ${pageUrl(r.brand, "subscriptions")}?utm_source=qr&utm_medium=ooh`);
}
if (!only || only === "saltline") {
  const s = await saltline();
  results.push(`Saltline console: http://localhost:3000/dashboard/pages/${s.brand.slug}`);
  for (const p of s.pages) results.push(`  ${p.page.title}: ${pageUrl(s.brand, p.page.slug)}  (variants: ${p.variants.map((v: AnyDoc) => v.name).join(", ")})`);
  results.push(`  Lisbon as a Londoner: ${pageUrl(s.brand, "lisbon")}?city=London`);
  if (s.lead) results.push(`  Personal link for ${s.lead.name}: ${pageUrl(s.brand, "marseille")}?g=${s.lead.memberId}`);
}
console.log("\n" + results.join("\n"));
